<?php
namespace App\Models; use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany;
final class SettlementBatch extends Model { use HasUuids; protected $fillable=['tenant_id','carrier_id','settlement_number','period_start','period_end','net_amount_minor','currency','status','prepared_by','approved_by','approved_at','idempotency_key','content_hash','submitted_at','paid_at','bank_reference','failure_reason','reversed_by','calculation_basis','partner_id','calculation_summary','calculated_at','reviewed_by','reviewed_at','processing_at','settled_at','reconciled_at','reconciliation_reference','correlation_id']; protected function casts():array{return['approved_at'=>'datetime','submitted_at'=>'datetime','paid_at'=>'datetime','calculation_summary'=>'array','calculated_at'=>'datetime','reviewed_at'=>'datetime','processing_at'=>'datetime','settled_at'=>'datetime','reconciled_at'=>'datetime'];} public function items():HasMany{return$this->hasMany(SettlementItem::class,'settlement_batch_id');} }
